<?php
/*
 * Invoices, payments and stock movements for the RivetMSP user-guide demo (group 6).
 *
 *   RIVETIT_APP_DIR=<app dir> php docs/user-guide/tools/seed/54-invoices.php
 *
 * 36 invoices over about six months for nine clients, covering every status the app uses: Draft (3), Sent (6), Viewed (3),
 * Partial (2), Paid (20), Cancelled (1) and Non-Billable (1). Four are past their due date (so the Overdue tile and red due dates
 * show), 23 were generated by the recurring invoices from seed 52, one was created from the Invoiced quote in seed 53,
 * and one carries a late-fee line like the one the nightly job adds. Paid and partial invoices get payments (ACH, check,
 * card), and invoice lines for stocked products take units out of stock, as the app does.
 * Late fees are switched on at 1.5 percent (only when they were still off) so the Invoices settings page shows the feature.
 * Depends on 00-core.sql, 50-billing-catalog.sql, 52-recurring-invoices.php and 53-quotes.php.
 * Idempotent: skips an invoice whose client, scope and date already exist.
 */
if (php_sapi_name() !== 'cli') {
    exit("Run this from the command line.\n");
}
$app = getenv('RIVETIT_APP_DIR') ?: getenv('RIVETMSP_APP_DIR') ?: '/tmp/rivetmsp-user-guide-demo';
if (!is_file($app . '/config.php')) {
    fwrite(STDERR, "54-invoices: no config.php in '$app'. Set RIVETIT_APP_DIR.\n");
    exit(1);
}
chdir($app . '/scripts');
require_once '../config.php';
require_once '../functions.php';

function q($sql) { global $mysqli; if (!mysqli_query($mysqli, $sql)) { fwrite(STDERR, "54-invoices: " . mysqli_error($mysqli) . "\n  $sql\n"); exit(1); } return true; }
function one($sql) { global $mysqli; $r = mysqli_query($mysqli, $sql); $row = $r ? mysqli_fetch_row($r) : null; return $row ? $row[0] : null; }
function e($s) { global $mysqli; return mysqli_real_escape_string($mysqli, (string) $s); }

$tz = (string) one('SELECT config_timezone FROM settings WHERE company_id = 1') ?: 'America/Chicago';
q("SET time_zone = '" . (new DateTime('now', new DateTimeZone($tz)))->format('P') . "'");

$tax_pct = (float) one("SELECT tax_percent FROM taxes WHERE tax_name = 'Sales Tax' LIMIT 1");

// Late fees: on at 1.5 percent, only when nobody has configured them yet
q("UPDATE settings SET config_invoice_late_fee_enable = 1, config_invoice_late_fee_percent = 1.50
   WHERE company_id = 1 AND config_invoice_late_fee_enable = 0 AND config_invoice_late_fee_percent = 0");

// Account the payments land in (same name and values as seed 55, which skips it when it already exists)
$acct = (int) one("SELECT account_id FROM accounts WHERE account_name = 'Lakeshore Business Checking' LIMIT 1");
if (!$acct) {
    q("INSERT INTO accounts SET account_name = 'Lakeshore Business Checking', opening_balance = 18500.00, account_currency_code = 'USD',
        account_notes = 'Main operating account. Client ACH and cheque payments land here.', account_type = 0");
    $acct = mysqli_insert_id($mysqli);
}

// Recurring invoice items by scope: copy the template items for the generated invoices
function recurring_items($client, $scope) {
    global $mysqli;
    $out = [];
    $r = mysqli_query($mysqli, "SELECT i.* FROM recurring_invoice_items i JOIN recurring_invoices r ON r.recurring_invoice_id = i.item_recurring_invoice_id
        JOIN clients c ON c.client_id = r.recurring_invoice_client_id WHERE c.client_name = '" . e($client) . "' AND r.recurring_invoice_scope = '" . e($scope) . "' ORDER BY i.item_order, i.item_id");
    while ($row = mysqli_fetch_assoc($r)) { $out[] = [$row['item_name'], (float) $row['item_quantity'], (float) $row['item_price'], $row['item_description']]; }
    return $out;
}
function quote_items($client, $scope) {
    global $mysqli;
    $out = [];
    $r = mysqli_query($mysqli, "SELECT i.* FROM quote_items i JOIN quotes r ON r.quote_id = i.item_quote_id
        JOIN clients c ON c.client_id = r.quote_client_id WHERE c.client_name = '" . e($client) . "' AND r.quote_scope = '" . e($scope) . "' ORDER BY i.item_order, i.item_id");
    while ($row = mysqli_fetch_assoc($r)) { $out[] = [$row['item_name'], (float) $row['item_quantity'], (float) $row['item_price'], $row['item_description']]; }
    return $out;
}

$R = [  // recurring invoice scopes, to keep the table below readable
  'N'  => ['Northshore Dental Group', 'Managed IT services - monthly'],
