  'Bl' => ['Bluebird Early Learning', 'Non-profit support plan - monthly'],
  'K'  => ['Kestrel Property Management', 'Office IT - monthly'],
];

// [client, scope, age in days, status, category, discount, recurring key or null, items or null (copied from recurring), payments, extra]
// payment: [days after invoice date, amount or 'full', method, reference]
// extra keys: quote (client, scope) to copy items from, late (percent) to add a Late Fee line, viewed (days ago), note
$ACH = 'ACH'; $CHK = 'Check'; $CC = 'Credit Card';
$inv = [
  ['Ironwood Logistics', 'Annual security training and vCIO reviews', 175, 'Paid', 'Consulting', 0, 'IY', null, [[19, 'full', $ACH, 'ACH-440186']], []],
  ['Northshore Dental Group', 'Operatory workstation replacement', 130, 'Paid', 'Hardware', 0, null, [['Business Laptop 14 in', 4], ['Project Labor (per hour)', 4]], [[22, 'full', $ACH, 'ACH-512903']], []],
  ['Granite Peak Manufacturing', 'Plant switch upgrade', 100, 'Paid', 'Hardware', 0, null, [['24-port Managed Switch', 2], ['Project Labor (per hour)', 6], ['Cat6 Patch Cable 3 ft (10-pack)', 2]], [[31, 'full', $ACH, 'ACH-533207']], []],
  ['Cedar & Pine Architects', 'Break/fix support retainer - monthly', 100, 'Paid', 'Service', 0, 'C', null, [[12, 'full', $CHK, 'Check #3318']], []],
  ['Cedar & Pine Architects', 'Remote support - printer and file server issues', 85, 'Sent', 'Service', 0, null, [['Remote Support (per hour)', 5]], [], ['late' => 1.5, 'note' => 'Second reminder sent by e-mail.']],
  ['Lakeview Family Credit Union', 'Annual security awareness training', 95, 'Paid', 'Software and Licensing', 0, null, [['Security Awareness Training (per user, year)', 85]], [[3, 'full', $CC, 'Card payment 55102']], []],
  ['Lakeview Family Credit Union', 'Managed IT and compliance reporting - monthly', 87, 'Paid', 'Managed Services', 0, 'L', null, [[9, 'full', $ACH, 'ACH-601144']], []],
  ['Granite Peak Manufacturing', 'Managed services and plant network - monthly', 68, 'Paid', 'Managed Services', 0, 'G', null, [[26, 'full', $ACH, 'ACH-533811']], []],
  ['Northshore Dental Group', 'Managed IT services - monthly', 82, 'Paid', 'Managed Services', 0, 'N', null, [[7, 'full', $ACH, 'ACH-512977']], []],
  ['Birchwood Law Partners', 'Managed workstations and Microsoft 365 - monthly', 80, 'Paid', 'Managed Services', 0, 'B', null, [[10, 'full', $CHK, 'Check #7710']], []],
  ['Kestrel Property Management', 'Office firewall replacement', 75, 'Partial', 'Hardware', 0, null, [['Firewall Appliance (small office)', 1], ['Project Labor (per hour)', 3]], [[20, 400.00, $CHK, 'Check #1207']], []],
  ['Cedar & Pine Architects', 'Break/fix support retainer - monthly', 70, 'Paid', 'Service', 0, 'C', null, [[14, 'full', $CHK, 'Check #3351']], []],
  ['Lakeview Family Credit Union', 'Managed IT and compliance reporting - monthly', 57, 'Paid', 'Managed Services', 0, 'L', null, [[8, 'full', $ACH, 'ACH-601702']], []],
  ['Cedar & Pine Architects', 'Duplicate billing - studio plotter support', 55, 'Cancelled', 'Service', 0, null, [['On-site Support (per hour)', 2]], [], ['note' => 'Created twice by mistake. Cancelled.']],
  ['Northshore Dental Group', 'Managed IT services - monthly', 52, 'Paid', 'Managed Services', 0, 'N', null, [[11, 'full', $ACH, 'ACH-513480']], []],
  ['Bluebird Early Learning', 'Non-profit support plan - monthly', 51, 'Paid', 'Managed Services', 100.00, 'Bl', null, [[6, 'full', $CHK, 'Check #0418']], []],
  ['Birchwood Law Partners', 'Managed workstations and Microsoft 365 - monthly', 50, 'Paid', 'Managed Services', 0, 'B', null, [[9, 'full', $CHK, 'Check #7762']], []],
  ['Ironwood Logistics', 'Warehouse Wi-Fi survey and install', 48, 'Sent', 'Projects', 0, null, null, [], ['quote' => ['Ironwood Logistics', 'Warehouse Wi-Fi survey and install'], 'note' => 'Created from quote.']],
  ['Maple Street Veterinary Clinic', 'Support plan with included hours - monthly', 48, 'Paid', 'Managed Services', 0, 'Mp', null, [[5, 'full', $CC, 'Card payment 55871']], []],
  ['Kestrel Property Management', 'Office IT - monthly', 45, 'Paid', 'Managed Services', 0, 'K', null, [[12, 'full', $ACH, 'ACH-702215']], []],
  ['Granite Peak Manufacturing', 'Managed services and plant network - monthly', 38, 'Paid', 'Managed Services', 0, 'G', null, [[20, 'full', $ACH, 'ACH-534402']], []],
  ['Ironwood Logistics', 'Managed services - monthly', 34, 'Paid', 'Managed Services', 0, 'I', null, [[10, 'full', $ACH, 'ACH-440907']], []],
  ['Maple Street Veterinary Clinic', 'After-hours server restore', 33, 'Paid', 'Service', 0, null, [['After-hours Emergency Support (per hour)', 3]], [[8, 'full', $CC, 'Card payment 56020']], []],
  ['Lakeview Family Credit Union', 'Managed IT and compliance reporting - monthly', 27, 'Partial', 'Managed Services', 0, 'L', null, [[6, 2000.00, $ACH, 'ACH-602310']], []],
  ['Bluebird Early Learning', 'Non-profit support plan - monthly', 21, 'Paid', 'Managed Services', 100.00, 'Bl', null, [[6, 'full', $CHK, 'Check #0431']], []],
  ['Birchwood Law Partners', 'Managed workstations and Microsoft 365 - monthly', 20, 'Viewed', 'Managed Services', 0, 'B', null, [], ['viewed' => 14]],
  ['Maple Street Veterinary Clinic', 'Support plan with included hours - monthly', 18, 'Viewed', 'Managed Services', 0, 'Mp', null, [], ['viewed' => 16]],
  ['Kestrel Property Management', 'Office IT - monthly', 15, 'Sent', 'Managed Services', 0, 'K', null, [], []],
  ['Bluebird Early Learning', 'Printer troubleshooting (goodwill)', 12, 'Non-Billable', 'Service', 0, null, [['Remote Support (per hour)', 1, 0.00, 'Goodwill: no charge.']], [], []],
  ['Lakeview Family Credit Union', 'Compliance workshop (half day)', 9, 'Viewed', 'Consulting', 0, null, [['Compliance workshop (half day)', 1, 1200.00, 'Half-day working session with the compliance team and the branch managers.']], [], ['viewed' => 8]],
  ['Granite Peak Manufacturing', 'Managed services and plant network - monthly', 8, 'Sent', 'Managed Services', 0, 'G', null, [], []],
  ['Ironwood Logistics', 'Managed services - monthly', 4, 'Sent', 'Managed Services', 0, 'I', null, [], []],
  ['Northshore Dental Group', 'Managed IT services - monthly', 22, 'Sent', 'Managed Services', 0, 'N', null, [], []],
  ['Birchwood Law Partners', 'Conference room display install', 2, 'Draft', 'Projects', 0, null, [['Project Labor (per hour)', 3], ['Cat6 Patch Cable 3 ft (10-pack)', 1]], [], []],
  ['Lakeview Family Credit Union', 'Branch workstation setup', 1, 'Draft', 'Hardware', 0, null, [['Business Laptop 14 in', 2], ['Project Labor (per hour)', 2]], [], []],
  ['Northshore Dental Group', 'Hygiene room workstation add-on', 0, 'Draft', 'Hardware', 50.00, null, [['Business Laptop 14 in', 1], ['Project Labor (per hour)', 1]], [], []],
];
// Oldest first so invoice numbers rise with time
usort($inv, function ($a, $b) { return $b[2] <=> $a[2]; });

$count = 0;
foreach ($inv as [$client, $scope, $age, $status, $category, $discount, $rkey, $items, $pays, $extra]) {
    $c = mysqli_fetch_assoc(mysqli_query($mysqli, "SELECT client_id, client_net_terms FROM clients WHERE client_name = '" . e($client) . "' LIMIT 1"));
    if (!$c) { echo "54-invoices: client '$client' missing, skipped\n"; continue; }
    $cid = (int) $c['client_id'];
    $terms = (int) $c['client_net_terms'] ?: 30;
    if (one("SELECT invoice_id FROM invoices WHERE invoice_client_id = $cid AND invoice_scope = '" . e($scope) . "' AND invoice_date = DATE_SUB(CURDATE(), INTERVAL $age DAY)")) { continue; }
    $cat = (int) one("SELECT category_id FROM categories WHERE category_name = '" . e($category) . "' AND category_type = 'Income' LIMIT 1");

    if ($items === null) {
        $items = isset($extra['quote']) ? quote_items($extra['quote'][0], $extra['quote'][1]) : recurring_items($R[$rkey][0], $R[$rkey][1]);
    }
    $rid = 0;
    if ($rkey) { $rid = (int) one("SELECT recurring_invoice_id FROM recurring_invoices WHERE recurring_invoice_client_id = $cid AND recurring_invoice_scope = '" . e($R[$rkey][1]) . "' LIMIT 1"); }

    $rows = []; $total = 0.0;
    foreach ($items as $i => $it) {
        $p = mysqli_fetch_assoc(mysqli_query($mysqli, "SELECT product_id, product_type, product_price, product_description, product_tax_id FROM products WHERE product_name = '" . e($it[0]) . "' LIMIT 1"));
        $qty = (float) $it[1];
        $price = isset($it[2]) ? (float) $it[2] : (float) ($p['product_price'] ?? 0);
        $desc = $it[3] ?? ($p['product_description'] ?? '');
        $tid = $p ? (int) $p['product_tax_id'] : 0;
        $sub = round($price * $qty, 2);
        $tax = $tid ? round($sub * $tax_pct / 100, 2) : 0.0;
        $rows[] = [$it[0], $desc, $qty, $price, $sub, $tax, $sub + $tax, $i + 1, $tid, $p ? (int) $p['product_id'] : 0, $p ? $p['product_type'] : ''];
        $total += $sub + $tax;
    }
    $late_fee = 0.0;
    if (isset($extra['late'])) {
        $late_fee = round($total * $extra['late'] / 100, 2);
    }
    $amount = round($total + $late_fee - $discount, 2);

    $n = (int) one('SELECT config_invoice_next_number FROM settings WHERE company_id = 1');
    q('UPDATE settings SET config_invoice_next_number = ' . ($n + 1) . ' WHERE company_id = 1');
    $prefix = (string) one('SELECT config_invoice_prefix FROM settings WHERE company_id = 1');
    $key = bin2hex(random_bytes(16));

    q("INSERT INTO invoices SET invoice_prefix = '" . e($prefix) . "', invoice_number = $n, invoice_scope = '" . e($scope) . "', invoice_status = '$status',
        invoice_date = DATE_SUB(CURDATE(), INTERVAL $age DAY), invoice_due = DATE_ADD(DATE_SUB(CURDATE(), INTERVAL $age DAY), INTERVAL $terms DAY),
        invoice_discount_amount = $discount, invoice_amount = $amount, invoice_currency_code = 'USD', invoice_note = '" . e($extra['note'] ?? '') . "',
        invoice_url_key = '$key', invoice_created_at = DATE_SUB(NOW(), INTERVAL $age DAY), invoice_category_id = $cat,
        invoice_recurring_invoice_id = $rid, invoice_client_id = $cid");
    $iid = mysqli_insert_id($mysqli);

    foreach ($rows as [$name, $desc, $qty, $price, $sub, $tax, $tot, $ord, $tid, $pid, $ptype]) {
        q("INSERT INTO invoice_items SET item_name = '" . e($name) . "', item_description = '" . e($desc) . "', item_quantity = $qty, item_price = $price,
            item_subtotal = $sub, item_tax = $tax, item_total = $tot, item_order = $ord, item_tax_id = $tid, item_product_id = $pid, item_invoice_id = $iid");
        if ($ptype === 'product') {
            q("INSERT INTO product_stock SET stock_qty = -" . (int) $qty . ", stock_note = 'QTY " . (int) $qty . " - Invoice $iid', stock_product_id = $pid,
                stock_created_at = DATE_SUB(NOW(), INTERVAL $age DAY)");
        }
    }
    if ($late_fee > 0) {
        $ord = count($rows) + 1;
        $pct = rtrim(rtrim(number_format($extra['late'], 2, '.', ''), '0'), '.');
        q("INSERT INTO invoice_items SET item_name = 'Late Fee', item_description = '$pct% late fee applied on ' , item_quantity = 1, item_price = $late_fee,
            item_subtotal = $late_fee, item_tax = 0, item_total = $late_fee, item_order = $ord, item_tax_id = 0, item_invoice_id = $iid");
        q("UPDATE invoice_items SET item_description = CONCAT('$pct% late fee applied on ', DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL " . ($age - 60) . " DAY), '%Y-%m-%d'))
            WHERE item_invoice_id = $iid AND item_name = 'Late Fee'");
    }

    // History
    $h = function ($ago, $st, $text) use ($iid) {
        q("INSERT INTO history SET history_status = '" . e($st) . "', history_description = '" . e($text) . "', history_invoice_id = $iid, history_created_at = DATE_SUB(NOW(), INTERVAL $ago DAY)");
    };
    if ($rid) {
        $h($age, 'Sent', 'Invoice Generated from Recurring!');
        if ($status !== 'Draft') { $h($age, 'Sent', 'Cron Emailed Invoice!'); }
    } elseif (isset($extra['quote'])) {
        $qn = mysqli_fetch_assoc(mysqli_query($mysqli, "SELECT q.quote_prefix, q.quote_number FROM quotes q JOIN clients c ON c.client_id = q.quote_client_id
            WHERE c.client_name = '" . e($extra['quote'][0]) . "' AND q.quote_scope = '" . e($extra['quote'][1]) . "' LIMIT 1"));
        $h($age, 'Draft', 'Invoice created from quote ' . ($qn ? $qn['quote_prefix'] . $qn['quote_number'] : ''));
        $h($age, 'Sent', 'Invoice marked sent by Jules Whitaker');
    } else {
        $h($age, 'Draft', 'Invoice created by Jules Whitaker');
        if ($status !== 'Draft' && $status !== 'Non-Billable') { $h($age, 'Sent', 'Invoice marked sent by Jules Whitaker'); }
    }
    if (isset($extra['viewed'])) { $h($extra['viewed'], 'Viewed', 'Invoice viewed - 198.51.100.' . (20 + $age % 40) . ' - Windows - Chrome'); }
    if ($late_fee > 0) {
        $h($age - 31, 'Sent', 'Cron Emailed Overdue Invoice');
        $h($age - 60, 'Sent', 'Cron applied a late fee of ' . number_format($late_fee, 2, '.', ''));
    }
    if ($status === 'Cancelled') { $h($age - 3, 'Cancelled', 'Invoice cancelled by Jules Whitaker'); }
    if ($status === 'Non-Billable') { $h($age, 'Non-Billable', 'INVOICE marked Non-Billable'); }

    // Payments
    $paid = 0.0;
    foreach ($pays as [$after, $amt, $method, $ref]) {
        $amt = $amt === 'full' ? $amount : (float) $amt;
        $paid += $amt;
        $pd = max(0, $age - $after);
        q("INSERT INTO payments SET payment_date = DATE_SUB(CURDATE(), INTERVAL $pd DAY), payment_amount = $amt, payment_currency_code = 'USD',
            payment_method = '" . e($method) . "', payment_reference = '" . e($ref) . "', payment_account_id = $acct, payment_invoice_id = $iid,
            payment_created_at = DATE_SUB(NOW(), INTERVAL $pd DAY)");
        $h($pd, $status === 'Paid' ? 'Paid' : 'Partial', 'Payment added');
    }
    $count++;
}

// The quote that became an invoice: add the "Quote invoiced as" line next to the quote's own history
$qrow = mysqli_fetch_assoc(mysqli_query($mysqli, "SELECT q.quote_id, q.quote_prefix, q.quote_number FROM quotes q JOIN clients c ON c.client_id = q.quote_client_id
    WHERE c.client_name = 'Ironwood Logistics' AND q.quote_scope = 'Warehouse Wi-Fi survey and install' AND q.quote_status = 'Invoiced' LIMIT 1"));
$irow = mysqli_fetch_assoc(mysqli_query($mysqli, "SELECT i.invoice_prefix, i.invoice_number FROM invoices i JOIN clients c ON c.client_id = i.invoice_client_id
    WHERE c.client_name = 'Ironwood Logistics' AND i.invoice_scope = 'Warehouse Wi-Fi survey and install' LIMIT 1"));
if ($qrow && $irow && !one("SELECT history_id FROM history WHERE history_quote_id = " . (int) $qrow['quote_id'] . " AND history_status = 'Invoiced'")) {
    q("INSERT INTO history SET history_status = 'Invoiced', history_description = 'Quote invoiced as " . e($irow['invoice_prefix'] . $irow['invoice_number']) . "', history_quote_id = " . (int) $qrow['quote_id'] . ", history_created_at = DATE_SUB(NOW(), INTERVAL 48 DAY)");
}
echo "54-invoices: $count invoices created\n";
